// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;

    function setUp() public { c = new W_WALLET(address(new Log())); }

    // fuzzed params: actor (as uint160 -> address), deposit amount, collect amount
    function testFuzz_property(uint160 actorRaw, uint256 depositAmt, uint256 collectAmt) public {
        vm.assume(depositAmt <= VALUE_CAP);
        // keep values wide but sensible
        address actor = address(actorRaw);
        vm.assume(actor != address(0));
        // bound deposit to be at least MinSum and reasonably small
        uint256 min = c.MinSum();
        depositAmt = bound(depositAmt, min, 10 ether);
        // collect amount between 1 and depositAmt
        collectAmt = bound(collectAmt, 1 wei, depositAmt);

        // Fund actor
        vm.deal(actor, depositAmt + 1 ether);

        // Actor calls Put to deposit and set unlockTime to past so Collect can run
        vm.prank(actor);
        c.Put(0); // payable call with no value yet
        // need to actually send Ether with Put
        vm.prank(actor);
        bool okPut; try c.Put{value: depositAmt}(uint256(0)) { okPut = true; } catch { okPut = false; }
        require(okPut, "Put failed in setup");

        // Ensure unlockTime is in the past so Collect condition (block.timestamp > unlockTime) holds
        vm.warp(block.timestamp + 1);

        // First Collect attempt: should succeed on reference
        bool ok1;
        vm.prank(actor);
        try c.Collect(collectAmt) { ok1 = true; } catch { ok1 = false; }
        // ok1 should be true on the reference; the mutant may still allow first call or may revert depending on Log behavior,
        // but crucial property concerns ability to call Collect again after the first completes.
        // Make a second Collect attempt: if the contract's reentrancy lock was correctly reset, this second call may succeed (if balance still >= collectAmt and other conditions).

        bool ok2;
        vm.prank(actor);
        try c.Collect(collectAmt) { ok2 = true; } catch { ok2 = false; }

        // GENERAL RULE (assertion): On the reference contract, if the first Collect succeeded (ok1 == true)
        // then the contract's reentrancy guard was reset and a second Collect attempt will NOT be permanently blocked by the reentrancy lock alone.
        // We express this by asserting that either the second call succeeds (ok2 == true) OR it fails only due to insufficient balance or MinSum,
        // which we detect by comparing recorded Acc balance before second call via the public getter.

        // Read holder state via public getter
        (uint256 unlockTime, uint256 balanceAfter) = c.Acc(actor);

        // If after first Collect the balance is still >= MinSum and >= collectAmt and unlockTime < block.timestamp,
        // then a second Collect should succeed on the correct contract. So assert that if those conditions hold then ok2 == true.
        bool conditionsPermit = (balanceAfter >= c.MinSum() && balanceAfter >= collectAmt && block.timestamp > unlockTime);

        assertTrue(!conditionsPermit || ok2);
    }
}
